class Fraction:
    def __init__(self, top, bottom):
        self.num = top
        self.den = bottom

    def __str__(self):
        return f'{self.num}/{self.den}'

    def __repr__(self):
        return f'Fraction({self.num}, {self.den})'

f = Fraction(3, 4)
print(f)
print([f])

class Stack:
    def __init__(self):
        self._items = []

    def push(item):
        self._items.append(item)

s = Stack()
s.push(42)

class Node:
    def __init__(self, node_data):
        self._data = node_data

    @property
    def data(self):
        return self._data

    @data.setter
    def data(self, new_data):
        self._data = new_data

n = Node(93)
n.data = 26
print(n.data, n._data)
